"""Invoice retry policy."""

from dataclasses import dataclass
from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - Python < 3.11
    import tomli as tomllib  # type: ignore[no-redef]

from src.common.settings import config_path


@dataclass(frozen=True)
class InvoiceRetryPolicy:
    initial_delay_seconds: int
    max_attempts: int
    backoff_multiplier: int


def load_invoice_retry_policy() -> InvoiceRetryPolicy:
    path: Path = config_path("retry_policy.toml")
    section: dict = {}
    if path.exists():
        with path.open("rb") as file:
            data = tomllib.load(file)
        section = data.get("invoice_retry", {})

    return InvoiceRetryPolicy(
        initial_delay_seconds=section.get("initial_delay_seconds", 30),
        max_attempts=section.get("max_attempts", 5),
        backoff_multiplier=section.get("backoff_multiplier", 2),
    )
